"""
    Subtract two vectors or a vector and a scalar element-wise

    Parameters
    ----------
    a: list[]
        A vector of scalar values
    b: list[]
        A vector of scalar values or a scalar value.

    Returns
    -------
    list[]
        A vector difference of a and b

    """
def vec_sub(a: Any, b: Any) -> object {
    if (`type(b) is `list) {
        assert (len(a) == len(b));
        return [*map(lambda (ai: Any, bi: Any) { (ai - bi); }, a, b)];
    } else {
        return [*map(lambda (ai: Any) { (ai - b); }, a)];
    }
}

