    Identifies the position of duplicated sequences
    """
def list_duplicates_of(seq: Any, item: Any) -> object {
    start_at = -1;
    locs = [];
    while True {
        try {
            loc = seq.index(item, (start_at + 1));
        } except ValueError {
            break;
        } else {
            locs.append(loc);
            start_at = loc;
        }
    }
    return locs;
}

